  const getMatchingLocation = (locStr: string) => {
    const norm = locStr.toLowerCase();
    return locationsData.find((l) => {
      const name = l.name.toLowerCase();
      if (name.includes('jvc') && (norm.includes('jvc') || norm.includes('jumeirah village circle'))) return true;
      if (name.includes('jvt') && (norm.includes('jvt') || norm.includes('jumeirah village triangle'))) return true;
      
      const cleanName = name.replace(/\(.*\)/, '').trim();
      const cleanProjectLoc = norm.split(',')[0].trim();
      
      if (cleanProjectLoc.includes(cleanName) || cleanName.includes(cleanProjectLoc)) return true;
      if (norm.includes(cleanName) || cleanName.includes(norm)) return true;
      return false;
    });
  };

  const matchingLoc = getMatchingLocation(project.location);
  const infoBar = useInView(0.1);
  const overview = useInView(0.1);
  const amenities = useInView(0.1);
  const gallery = useInView(0.05);
  const aboutProp = useInView(0.1);
  const aboutLoc = useInView(0.1);
  const quoteSection = useInView(0.1);
  const contactSection = useInView(0.1);
  const nextSection = useInView(0.1);

  const galleryScrollRef = useRef<HTMLDivElement>(null);
  const [showAllImages, setShowAllImages] = useState(false);
