export const projects: ProjectDetail[] = allProjects
  .filter(p => !p.hidden)
  .sort((a, b) => {
    const order = [
      'sakura-gardens',
      'ellington-meriva-signature',
      'the-highgrove-ellington-mbr-city',
      'damac-islands-2',
      'golf-greens-damac-hills',
      'chelsea-residences-damac',
      'city-walk-crestlane-meraas',
      'golf-trails-emaar-south',
      'berkeley-square-south',
      'binghatti-sky-terraces',
      'tilal-binghatti',
      'jacob-co-beachfront-living-ohana',
      'greenz-by-danube',
      'eltiera-views-ellington',
      'portside-square-ellington',
      'hilton-residences-dubai-maritime-city',
      'kanyon-by-beyond'
    ];
    return order.indexOf(a.id) - order.indexOf(b.id);
  });

export function getProjectBySlug(slug: string): ProjectDetail | undefined {
  return projects.find((p) => p.slug === slug);
}

export function getNextProject(currentSlug: string): ProjectDetail {
  const idx = projects.findIndex((p) => p.slug === currentSlug);
  return projects[(idx + 1) % projects.length];
}

export function getPreviousProject(currentSlug: string): ProjectDetail {
  const idx = projects.findIndex((p) => p.slug === currentSlug);
  return projects[(idx - 1 + projects.length) % projects.length];
}