'use client';
import React from 'react';
import Link from 'next/link';

interface BreadcrumbItem {
  label: string;
  href?: string;
}

interface BreadcrumbProps {
  items: BreadcrumbItem[];
}

export default function Breadcrumb({ items }: BreadcrumbProps) {
  return (
    <nav
      aria-label="Breadcrumb"
      style={{
        display: 'flex',
        alignItems: 'center',
        gap: '8px',
        flexWrap: 'wrap',
      }}
    >
      {items.map((item, index) => {
        const isLast = index === items.length - 1;
        return (
          <React.Fragment key={index}>
            {index > 0 && (
              <span
                style={{
                  color: 'rgba(224,201,150,0.4)',
                  fontSize: 'clamp(10px, 1vw, 12px)',
                  userSelect: 'none',
                }}
                aria-hidden="true"
              >
                /
              </span>
            )}
            {!isLast && item.href ? (
              <Link
                href={item.href}
                style={{
                  fontFamily: '"Uxum Grotesque Regular", sans-serif',
                  fontSize: 'clamp(10px, 1vw, 12px)',
                  color: 'rgba(224,201,150,0.6)',
                  textDecoration: 'none',
                  letterSpacing: '0.12em',
                  textTransform: 'uppercase',
                  transition: 'color 0.2s ease',
                }}
                onMouseEnter={(e) => { (e.currentTarget as HTMLAnchorElement).style.color = '#e0c996'; }}
                onMouseLeave={(e) => { (e.currentTarget as HTMLAnchorElement).style.color = 'rgba(224,201,150,0.6)'; }}
              >
                {item.label}
              </Link>
            ) : (
              <span
                aria-current={isLast ? 'page' : undefined}
                style={{
                  fontFamily: '"Uxum Grotesque Regular", sans-serif',
                  fontSize: 'clamp(10px, 1vw, 12px)',
                  color: '#e0c996',
                  letterSpacing: '0.12em',
                  textTransform: 'uppercase',
                }}
              >
                {item.label}
              </span>
            )}
          </React.Fragment>
        );
      })}
    </nav>
  );
}
